insert into pg_temp.element_catalog_seed_rows
  (element_key, apparatus, element_group, value_letter, value_points, fig_reference, name, short_name, description, source_page, source_checked_on, drafted_by, drafted_on, batch, review_status, reviewed_on)
values
  ('ub_seat_circle_fwd_straddle_cut_regrasp_same_bar', 'uneven_bars', '5', 'A', null, '5.101', 'Vuelta sentada adelante carpada y piernas abiertas atrás a suspensión', 'Vuelta sentada con piernas abiertas', 'Sirve en cualquiera de las dos barras. Desde apoyo dorsal, la gimnasta da una vuelta sentada adelante con el cuerpo carpado, suelta, saca las piernas abiertas hacia atrás y vuelve a agarrar la misma barra en suspensión.', 94, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_underswing_bwd_dislocate_to_hang_hb', 'uneven_bars', '5', 'A', null, '5.104', 'Schleudern a suspensión en la barra alta', 'Schleudern', 'Acaba en suspensión en la misma barra alta. La dislocación llega tras un único balanceo por debajo de la barra, hacia atrás, hecho ya en posición carpada invertida.', 96, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_sole_circle_fwd', 'uneven_bars', '5', 'A', null, '5.105', 'Vuelta de plantas adelante', 'Vuelta de plantas adelante', 'Con las plantas apoyadas en la barra y el cuerpo carpado, gira hacia delante alrededor de ella. Si lleva las piernas abiertas, cuenta igual.', 97, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_sole_circle_fwd_l_grip', 'uneven_bars', '5', 'A', null, '5.106', 'Vuelta de plantas adelante en presa cubital', 'Vuelta de plantas adelante en cubital', 'Las manos van en presa cubital mientras gira adelante con las plantas en la barra y el cuerpo carpado; abriendo las piernas vale lo mismo.', 97, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_sole_circle_bwd', 'uneven_bars', '5', 'A', null, '5.108', 'Vuelta de plantas atrás', 'Vuelta de plantas atrás', 'Gira hacia atrás alrededor de la barra con las plantas apoyadas en ella, carpada o con las piernas abiertas: las dos formas cuentan igual.', 98, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_seat_circle_bwd_hb_release_to_lb', 'uneven_bars', '5', 'B', null, '5.202', 'Vuelta sentada atrás en la barra alta con vuelo a la barra baja', 'Vuelta sentada atrás a barra baja', 'Empieza sentada en apoyo dorsal sobre la barra alta. Da una vuelta sentada atrás carpada, suelta y vuela hasta agarrarse en suspensión a la barra baja.', 95, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_toe_underswing_lb_counter_flight_to_hb', 'uneven_bars', '5', 'B', null, '5.207', 'Balanceo con los pies en la barra baja y vuelo adelante a la barra alta', 'Pies en barra baja a barra alta', 'La gimnasta sale de la vertical en la barra baja, baja con los pies en la barra y el cuerpo carpado, suelta y, invirtiendo el sentido del balanceo, vuela hacia delante hasta la suspensión en la barra alta.', 98, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_outer_rear_support_hb_straddle_cut_over_lb', 'uneven_bars', '5', 'C', null, '5.301', 'Piernas abiertas atrás con cambio de barra a suspensión', 'Piernas abiertas y cambio de barra', 'Saca las piernas abiertas hacia atrás y cambia de barra hasta la suspensión en la otra. De la alta a la baja, sale de apoyo dorsal por fuera, cayendo atrás o con vuelta sentada adelante, y pasa las piernas sobre la baja; desde apoyo dorsal en la baja, cambia de presa y vuela a la alta.', 94, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_clear_pike_full_circle_bwd_to_clear_rear_support_hb', 'uneven_bars', '5', 'C', null, '5.302', 'Vuelta carpada libre atrás completa a apoyo dorsal libre (Steinemann)', 'Steinemann', 'Las piernas, juntas, no tocan la barra en toda la vuelta: desde apoyo dorsal carpado libre en la barra alta, da una vuelta carpada libre atrás completa y termina en apoyo dorsal libre.', 95, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_clear_pike_full_circle_bwd_stoop_out_to_hang_hb', 'uneven_bars', '5', 'C', null, '5.303', 'Vuelta carpada libre atrás completa y salida atrás a suspensión (Li Li)', 'Li Li (vuelta a suspensión)', 'Termina en suspensión en la barra alta: tras una vuelta carpada libre atrás completa con las piernas juntas, sin tocar la barra, las saca juntas hacia atrás entre las manos.', 95, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dislocate_hop_to_regular_grip_near_handstand_hb', 'uneven_bars', '5', 'C', null, '5.304', 'Schleudern con cambio de presa casi a la vertical', 'Schleudern a casi vertical (Alt)', 'Cerca de la vertical y en presa dorsal termina esta dislocación carpada atrás en la barra alta, con un saltito de manos para cambiar de presa. Otra forma lleva el apellido de la gimnasta Alt: piernas juntas entre las manos, dislocación, medio giro (180°) y vuelo a la baja.', 96, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_pike_sole_circle_fwd_reverse_grip_to_handstand', 'uneven_bars', '5', 'C', null, '5.305', 'Vuelta de plantas adelante en presa palmar a la vertical', 'Vuelta de plantas adelante a vertical', 'Termina en la vertical. En presa palmar, gira hacia delante carpada con las plantas en la barra y sube; también vale si hace medio giro (180°) mientras sube a la vertical.', 97, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_pike_sole_circle_fwd_l_grip_to_handstand', 'uneven_bars', '5', 'C', null, '5.306', 'Vuelta de plantas adelante en presa cubital a la vertical', 'Vuelta de plantas cubital a vertical', 'Con o sin medio giro (180°) al subir, es el mismo elemento: vuelta adelante carpada con las plantas apoyadas en la barra y presa cubital, hasta la vertical.', 97, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_toe_underswing_release_1_5_turn_regrasp', 'uneven_bars', '5', 'C', null, '5.307', 'Balanceo con los pies en la barra, suelta con giro y medio y vuelve a agarrar (Burda)', 'Burda (Hamelin)', 'Giro y medio (540°) en el aire: desde la vertical, baja con los pies en la barra y carpada, suelta, gira estirada y vuelve a la misma barra en suspensión. Vale en cualquier barra. Hamelin: mortal atrás extendido de la barra alta a apoyo libre en la baja.', 98, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_pike_sole_circle_bwd_to_handstand', 'uneven_bars', '5', 'C', null, '5.308', 'Vuelta de plantas atrás a la vertical', 'Vuelta de plantas atrás a vertical', 'Llegar a la vertical es lo que cuenta tras la vuelta atrás carpada con las plantas en la barra; arriba puede dar medio giro (180°) o pasar a presa palmar con un saltito de manos sin cambiar de elemento.', 98, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_clear_pike_full_circle_bwd_over_hb_to_hang', 'uneven_bars', '5', 'D', null, '5.402', 'Vuelta carpada libre atrás por encima de la barra a suspensión', 'Mirgoradskaja (Krasnyanska)', 'Termina en suspensión tras cruzar por encima de la barra alta. Las piernas, juntas, no la tocan: la vuelta carpada libre atrás sale del apoyo dorsal carpado libre y vuelve a pasar por él sin detenerse. Krasnyanska: de la vertical a apoyo dorsal invertido carpado.', 95, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_clear_pike_full_circle_bwd_counter_straddle_flight', 'uneven_bars', '5', 'D', null, '5.403', 'Vuelta carpada libre atrás completa con vuelo de piernas abiertas (Li Li)', 'Li Li (con vuelo)', 'Tras la vuelta carpada libre atrás completa con las piernas juntas en la barra alta, suelta y vuela hacia atrás en sentido contrario al balanceo, abre las piernas en el aire y vuelve a agarrar la misma barra.', 95, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_underswing_dislocate_flight_to_handstand_lb', 'uneven_bars', '5', 'D', null, '5.404', 'Schleudern de la barra alta a la vertical en la baja', 'Zuchold', 'Cambia de barra con la dislocación: en la alta, un único balanceo atrás por debajo en posición carpada invertida, suelta y llega a la vertical en la baja. Vale también si entra pasando las piernas juntas entre las manos.', 96, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_pike_sole_circle_fwd_reverse_grip_full_turn_handstand', 'uneven_bars', '5', 'D', null, '5.405', 'Vuelta adelante con los pies en la barra en presa palmar y giro completo a la vertical (Hoefnagel)', 'Hoefnagel', 'Giro completo (360°) mientras sube a la vertical: es una vuelta adelante carpada con los pies en la barra, en presa palmar.', 97, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_pike_sole_circle_fwd_l_grip_full_turn_handstand', 'uneven_bars', '5', 'D', null, '5.406', 'Vuelta de plantas adelante en presa cubital y giro completo a la vertical', 'Vuelta de plantas en cubital con giro', 'En presa cubital, la vuelta adelante con las plantas en la barra y el cuerpo carpado termina en la vertical con un giro completo (360°) durante la subida.', 97, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_pike_sole_circle_bwd_full_turn_handstand', 'uneven_bars', '5', 'D', null, '5.408', 'Vuelta de plantas atrás y giro completo a la vertical', 'Vuelta de plantas atrás con giro', 'Sube a la vertical haciendo un giro completo (360°) después de una vuelta atrás carpada con las plantas apoyadas en la barra.', 98, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_pike_sole_circle_bwd_lb_through_handstand_flight_to_hb', 'uneven_bars', '5', 'D', null, '5.409', 'Vuelta de plantas atrás de la barra baja a la alta', 'Maloney', 'Vuela a la barra alta y la agarra en suspensión después de pasar por la vertical en una vuelta atrás carpada con las plantas en la barra baja. Empieza en apoyo facial, mirando hacia la alta.', 99, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_pike_sole_circle_bwd_straddle_reverse_hecht_over_hb', 'uneven_bars', '5', 'D', null, '5.410', 'Vuelta atrás con los pies en la barra y hecht atrás con piernas abiertas sobre la barra alta (Ray)', 'Ray (Tweddle)', 'Hecht hacia atrás con piernas abiertas que cruza por encima de la barra alta: tras la vuelta atrás con los pies en la barra desde la vertical, suelta contra el balanceo y vuelve a agarrar. Tweddle: con medio giro (180°) y presa mixta cubital.', 99, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_stoop_in_clear_pike_circle_fwd_to_handstand_l_grip', 'uneven_bars', '5', 'E', null, '5.501', 'Vuelta libre adelante con piernas entre las manos a la vertical', 'Luo', 'La vertical final no puede desviarse más de 30°, haga o no medio giro (180°) al subir; sin giro, acaba en presa cubital. Para llegar, mete las piernas carpadas entre las manos (posición Adler) y da la vuelta adelante sin que toquen la barra.', 94, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_clear_pike_circle_bwd_salto_bwd_to_lb', 'uneven_bars', '5', 'E', null, '5.502', 'Vuelta carpada libre atrás y mortal extendido a la barra baja', 'Teza', 'Apoyo libre en la barra baja tras un mortal atrás extendido que sale de la vuelta carpada libre atrás en la alta, con las piernas juntas. Otra forma cambia el mortal por un medio giro (180°) en el vuelo y llega a la vertical en la baja.', 95, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_pike_sole_circle_bwd_1_5_turn_handstand', 'uneven_bars', '5', 'E', null, '5.508', 'Vuelta atrás con los pies en la barra y giro y medio a la vertical (Lucke)', 'Lucke', 'Giro y medio (540°) mientras sube a la vertical, al terminar una vuelta atrás carpada con los pies en la barra.', 98, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_pike_sole_circle_bwd_lb_flight_half_turn_to_hb', 'uneven_bars', '5', 'E', null, '5.509', 'Vuelta de plantas atrás en la baja con medio giro a la alta', 'Van Leeuwen (Seitz)', 'Medio giro (180°) en el vuelo hacia la barra alta; Seitz lo hace con giro completo (360°). Parte de la vertical en la barra baja, de espaldas a la alta, baja con las plantas en la barra, vuelve a pasar por la vertical y suelta.', 99, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_pike_sole_circle_bwd_pike_reverse_hecht_over_hb', 'uneven_bars', '5', 'E', null, '5.510', 'Hecht atrás carpado sobre la barra alta', 'Church (Fenton)', 'Un hecht hacia atrás en carpado cruza la barra alta por encima, contra el balanceo, y la gimnasta la vuelve a agarrar. Antes, desde la vertical, hace la vuelta atrás con los pies en la barra. Fenton añade medio giro (180°) y acaba en presa mixta cubital.', 99, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_toe_underswing_hb_counter_salto_fwd_straddled_reverse_grip', 'uneven_bars', '5', 'F', null, '5.607', 'Balanceo con los pies en la barra alta y mortal adelante con piernas abiertas a presa palmar', 'Kim (pies en la barra)', 'Es el Kim, un mortal de vuelta a la misma barra: en la vertical sobre la barra alta, de espaldas a la baja, baja con los pies en la barra, suelta contra el balanceo y hace un mortal adelante con las piernas abiertas para volver a agarrar la misma barra en presa palmar.', 98, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_pike_sole_circle_bwd_layout_reverse_hecht_over_hb', 'uneven_bars', '5', 'F', null, '5.610', 'Hecht atrás extendido sobre la barra alta', 'Nabieva (Derwael)', 'Vuelve a agarrar la barra alta después de cruzarla por encima con el cuerpo extendido, en un hecht hacia atrás contra el balanceo que sale de la vuelta atrás con los pies en la barra. Derwael: con medio giro (180°), termina en presa mixta cubital.', 99, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_underswing_half_turn_to_stand', 'uneven_bars', '6', 'A', null, '6.101', 'Salida con balanceo por debajo de la barra y medio giro', 'Salida con medio giro', 'Sin mortal: desde la vertical en la barra alta, baja con balanceo por debajo de la barra, suelta y hace medio giro (180°) en el aire antes de caer de pie. Con giro completo (360°) cuenta igual.', 100, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_clear_underswing_half_turn_to_stand', 'uneven_bars', '6', 'A', null, '6.102', 'Salida con balanceo libre y medio giro', 'Balanceo libre y medio giro', 'Medio giro (180°) o giro completo (360°) en el vuelo, sin mortal, para caer de pie. Antes de soltar, baja de la vertical en la barra alta con un balanceo libre por debajo de la barra.', 100, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_flyaway_salto_bwd', 'uneven_bars', '6', 'A', null, '6.104', 'Salida en mortal atrás desde balanceo largo adelante (flyaway)', 'Flyaway', 'El clásico flyaway: desde suspensión, normalmente en la barra alta, hace un balanceo largo adelante, suelta y da un mortal atrás agrupado, carpado o extendido antes de caer de pie.', 102, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_swing_bwd_salto_fwd', 'uneven_bars', '6', 'A', null, '6.108', 'Salida en mortal adelante desde balanceo atrás', 'Salida mortal adelante', 'Agrupado, carpado o extendido, el mortal adelante sale del balanceo atrás desde suspensión y termina de pie. También vale soltar tras una vuelta libre adelante con piernas abiertas desde la vertical en la barra alta, con el mortal agrupado.', 105, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_underswing_salto_fwd', 'uneven_bars', '6', 'B', null, '6.201', 'Mortal adelante tras balanceo por debajo', 'Balanceo bajo y mortal adelante', 'Agrupado o carpado, un mortal adelante cierra este balanceo por debajo de la barra alta que empieza en la vertical. Cae de pie.', 100, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_flyaway_salto_bwd_half_turn', 'uneven_bars', '6', 'B', null, '6.204', 'Flyaway con media pirueta', 'Flyaway con media pirueta', 'Mortal atrás agrupado o extendido con media pirueta (180°) durante el mortal, soltando tras el balanceo largo adelante desde suspensión. Con pirueta completa (360°) también vale.', 102, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_double_salto_bwd_tucked', 'uneven_bars', '6', 'B', null, '6.205', 'Salida en doble mortal atrás agrupado', 'Doble mortal atrás agrupado', 'Después del balanceo largo adelante desde suspensión, normalmente en la barra alta, suelta y hace dos mortales atrás agrupados antes de llegar al suelo.', 103, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_swing_bwd_salto_fwd_half_turn', 'uneven_bars', '6', 'B', null, '6.208', 'Salida en mortal adelante con media pirueta desde balanceo atrás', 'Mortal adelante con media pirueta', 'Desde suspensión, aprovecha el balanceo atrás para soltar y hacer un mortal adelante agrupado o extendido con media pirueta (180°). Con pirueta completa (360°) cuenta lo mismo.', 105, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_hip_circle_hecht', 'uneven_bars', '6', 'B', null, '6.209', 'Salida en hecht desde vuelta atrás al apoyo', 'Hecht de salida', 'Vale en la barra baja o en la alta. Desde apoyo facial hace una vuelta atrás al apoyo (también puede ser libre) y sale volando en hecht con el cuerpo extendido, sin mortal, hasta caer de pie.', 106, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_on_hb_salto_fwd_tucked', 'uneven_bars', '6', 'B', null, '6.210', 'Mortal adelante agrupado desde la vertical en la barra alta', 'Mortal adelante desde la vertical', 'Encima de la barra alta, en la vertical, la gimnasta hace directamente un mortal adelante agrupado y cae de pie.', 106, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_underswing_salto_fwd_half_turn', 'uneven_bars', '6', 'C', null, '6.301', 'Salida con balanceo por debajo de la barra y mortal adelante con media pirueta', 'Balanceo bajo, mortal y media pirueta', 'Con media pirueta (180°) dentro del mortal adelante, agrupado o carpado: sale de la vertical en la barra alta con balanceo por debajo de la barra y suelta. Vale igual con pirueta completa (360°).', 100, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_clear_underswing_salto_fwd', 'uneven_bars', '6', 'C', null, '6.302', 'Balanceo libre y mortal adelante', 'Mortal adelante tras balanceo libre', 'Mortal adelante agrupado o carpado, con o sin media pirueta (180°), al soltar de un balanceo libre por debajo de la barra alta. Plichta (agrupado), Alt (agrupado, 180°) y Rodriguez (carpado, 180°) dan nombre a las formas que salen de una vuelta libre con piernas abiertas.', 100, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_underswing_half_turn_salto_bwd', 'uneven_bars', '6', 'C', null, '6.303', 'Salida con balanceo por debajo, medio giro y mortal atrás (Comaneci)', 'Comaneci (salida)', 'Primero el medio giro (180°), luego el mortal: desde la vertical en la barra alta baja con balanceo por debajo, gira, suelta y hace un mortal atrás agrupado o carpado. También vale con el balanceo libre.', 101, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_salto_bwd_stretched_one_and_half_turn', 'uneven_bars', '6', 'C', null, '6.304', 'Flyaway extendido con pirueta y media', 'Flyaway con pirueta y media', 'Mortal atrás extendido con pirueta y media (540°) tras el balanceo largo adelante desde suspensión; con doble pirueta (720°) cuenta igual.', 102, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_double_salto_bwd_piked', 'uneven_bars', '6', 'C', null, '6.305', 'Salida en doble mortal atrás carpado', 'Doble mortal atrás carpado', 'Cae de pie tras dos mortales atrás carpados, soltando la barra en el balanceo largo adelante desde suspensión.', 103, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_swing_bwd_salto_fwd_stretched_one_and_half_turn', 'uneven_bars', '6', 'C', null, '6.308', 'Mortal adelante extendido con pirueta y media', 'Pechstein (Fan)', 'El nombre Pechstein va solo con pirueta y media (540°) en un mortal adelante extendido tras el balanceo atrás; con doble pirueta (720°) cuenta igual, sin ese nombre. Fan, aparte, sale de presa cubital con medio giro (180°) y doble mortal atrás agrupado.', 105, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_hip_circle_hecht_full_turn', 'uneven_bars', '6', 'C', null, '6.309', 'Salida en hecht con giro completo desde vuelta atrás al apoyo', 'Hecht con giro completo', 'Durante el vuelo en hecht, con el cuerpo extendido, hace un giro completo (360°). Sale de apoyo facial con una vuelta atrás al apoyo, que puede ser libre, en cualquiera de las dos barras, y no hay mortal.', 106, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_on_hb_salto_fwd_piked', 'uneven_bars', '6', 'C', null, '6.310', 'Mortal adelante carpado desde la vertical en la barra alta', 'Mortal adelante carpado desde vertical', 'Un mortal adelante carpado que nace en la vertical, encima de la barra alta, y termina de pie. Vale también un mortal atrás agrupado o carpado desde esa misma vertical; el agrupado es el que se conoce como Delladio o Parolari.', 106, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_underswing_salto_fwd_tucked_one_and_half_turn', 'uneven_bars', '6', 'D', null, '6.401', 'Salida con balanceo por debajo y mortal adelante agrupado con pirueta y media', 'Mortal adelante pirueta y media (Moors)', 'Pirueta y media (540°) en un mortal adelante agrupado: viene de la vertical en la barra alta y de un balanceo por debajo de la barra. Moors: mortal adelante extendido con media pirueta (180°).', 100, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_clear_underswing_salto_fwd_tucked_full_turn', 'uneven_bars', '6', 'D', null, '6.402', 'Mortal adelante agrupado con pirueta tras balanceo libre', 'Mortal con pirueta (Brunner, Petz)', 'Pirueta completa (360°) en un mortal adelante agrupado al soltar de un balanceo libre por debajo de la barra alta. Petz hace ese mortal agrupado con pirueta completa (360°) tras una vuelta libre con piernas abiertas; Brunner, tras un balanceo libre carpado, extendido y con media pirueta (180°).', 100, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_underswing_half_turn_salto_bwd_stretched', 'uneven_bars', '6', 'D', null, '6.403', 'Medio giro y mortal atrás extendido', 'Mortal atrás extendido (Okino, Kraeker)', 'El medio giro (180°) llega antes de soltar, en el balanceo por debajo desde la vertical en la barra alta; después, mortal atrás extendido. Okino lo hace con balanceo libre. Kraeker: el mismo medio giro y luego mortal atrás agrupado con pirueta completa (360°).', 101, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_salto_bwd_stretched_two_and_half_turn', 'uneven_bars', '6', 'D', null, '6.404', 'Flyaway extendido con dos piruetas y media (Ji)', 'Ji', 'Dos piruetas y media (900°) dentro de un único mortal atrás extendido, soltando en el balanceo largo adelante desde suspensión.', 102, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_double_salto_bwd_full_turn', 'uneven_bars', '6', 'D', null, '6.405', 'Doble mortal atrás con pirueta en uno de los mortales', 'Morio (Chusovitina)', 'La pirueta completa (360°) va en un solo mortal de un doble mortal atrás agrupado o carpado que suelta en el balanceo largo adelante. Si va en el primer mortal es el Morio; si va en el segundo, el Chusovitina.', 103, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_double_salto_bwd_stretched', 'uneven_bars', '6', 'D', null, '6.406', 'Salida en doble mortal atrás extendido', 'Doble mortal atrás extendido', 'Normalmente desde la barra alta: balanceo largo adelante en suspensión, suelta y dos mortales atrás con el cuerpo extendido.', 103, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_salto_bwd_half_turn_into_salto_fwd_tucked', 'uneven_bars', '6', 'D', null, '6.407', 'Mortal atrás con media pirueta y mortal adelante, agrupados (Fontaine)', 'Fontaine', 'Los dos mortales van agrupados: el primero, atrás, lleva media pirueta (180°) y el segundo es adelante. Sale del balanceo largo adelante. También vale con medio giro (180°) antes de soltar y doble mortal adelante agrupado.', 104, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_swing_bwd_double_salto_fwd_tucked', 'uneven_bars', '6', 'D', null, '6.408', 'Salida en doble mortal adelante agrupado desde balanceo atrás', 'Doble mortal adelante agrupado (Okamura)', 'Doble mortal adelante agrupado tras soltar en el balanceo atrás desde suspensión. Okamura: desde presa cubital, medio giro (180°) antes de soltar y doble mortal atrás carpado.', 105, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_hip_circle_hecht_salto_bwd_tucked', 'uneven_bars', '6', 'D', null, '6.409', 'Hecht con mortal atrás agrupado', 'Mukhina', 'Al salir en hecht de una vuelta atrás al apoyo, que puede ser libre, mete un mortal atrás agrupado. Parte de apoyo facial y vale en cualquiera de las dos barras.', 106, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_clear_underswing_salto_fwd_tucked_one_and_half_turn', 'uneven_bars', '6', 'E', null, '6.502', 'Balanceo libre y mortal adelante agrupado con pirueta y media', 'Mortal adelante pirueta y media (Mesiri)', 'Mesiri es la forma sin pirueta, con el mortal adelante extendido. La principal mete pirueta y media (540°) en un mortal adelante agrupado, tras soltar de un balanceo libre por debajo de la barra alta desde la vertical.', 100, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_salto_bwd_stretched_triple_turn', 'uneven_bars', '6', 'E', null, '6.504', 'Flyaway extendido con triple pirueta (Bar)', 'Bar', 'Triple pirueta (1080°) en un mortal atrás extendido: así sale tras el balanceo largo adelante desde suspensión.', 102, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_double_salto_bwd_tucked_one_and_half_turn', 'uneven_bars', '6', 'E', null, '6.505', 'Doble mortal atrás agrupado con pirueta y media (Mustafina)', 'Mustafina', 'Pirueta y media (540°) en un doble mortal atrás agrupado, que sale del balanceo largo adelante en suspensión, normalmente en la barra alta.', 103, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_salto_bwd_half_turn_into_salto_fwd_stretched', 'uneven_bars', '6', 'E', null, '6.507', 'Mortal atrás con media pirueta y mortal adelante, extendidos (Blanco)', 'Blanco (Giovannini / Li Ya)', 'Extendida en los dos mortales: primero uno atrás con media pirueta (180°) y después otro adelante, tras el balanceo largo adelante. Giovannini / Li Ya: medio giro (180°) antes de soltar y doble mortal adelante carpado.', 104, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_swing_bwd_double_salto_fwd_tucked_half_turn', 'uneven_bars', '6', 'E', null, '6.508', 'Doble mortal adelante agrupado con media pirueta', 'Doble mortal adelante con media pirueta', 'Dos formas sueltan en el balanceo atrás: doble mortal adelante agrupado con media pirueta (180°), o mortal adelante con media pirueta seguido de uno atrás agrupado; solo esta última es el Arai. Stewart, aparte: doble mortal adelante carpado sin pirueta.', 105, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_hip_circle_hecht_half_turn_salto_fwd_tucked', 'uneven_bars', '6', 'E', null, '6.509', 'Hecht, medio giro y mortal adelante agrupado', 'Hecht con medio giro y mortal', 'Primero medio giro (180°) al salir en hecht y luego mortal adelante agrupado. El hecht sale de una vuelta atrás al apoyo, también libre, desde apoyo facial en la barra baja o en la alta.', 106, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_double_salto_bwd_tucked_double_turn', 'uneven_bars', '6', 'F', null, '6.605', 'Doble mortal atrás agrupado con doble pirueta (Fabrichnova)', 'Fabrichnova', 'Doble pirueta (720°) en un doble mortal atrás agrupado, soltando la barra en el balanceo largo adelante desde suspensión.', 103, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_double_salto_bwd_stretched_full_turn', 'uneven_bars', '6', 'F', null, '6.606', 'Doble mortal atrás extendido con pirueta completa', 'Doble atrás extendido con pirueta', 'Con el cuerpo extendido en los dos mortales atrás, mete una pirueta completa (360°) solo en uno de ellos, el primero o el segundo. Suelta en el balanceo largo adelante.', 103, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_swing_bwd_double_salto_fwd_piked_half_turn', 'uneven_bars', '6', 'F', null, '6.608', 'Doble mortal adelante carpado con media pirueta (Pentek)', 'Pentek', 'Tras el balanceo atrás desde suspensión, suelta y hace un doble mortal adelante carpado con media pirueta (180°).', 105, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_hip_circle_hecht_full_turn_salto_bwd_tucked', 'uneven_bars', '6', 'F', null, '6.609', 'Hecht con giro completo y mortal atrás agrupado (Ma)', 'Ma', 'Giro completo (360°) en el hecht antes del mortal atrás agrupado. Sale de apoyo facial con vuelta atrás al apoyo, que puede ser libre, en la barra baja o en la alta.', 106, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_double_salto_bwd_stretched_double_turn', 'uneven_bars', '6', 'G', null, '6.706', 'Doble mortal atrás extendido con doble pirueta (Ray)', 'Ray (salida)', 'Normalmente desde la barra alta: suelta en el balanceo largo adelante y hace dos mortales atrás extendidos con doble pirueta (720°).', 103, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null),
  ('ub_dismount_triple_salto_bwd_tucked', 'uneven_bars', '6', 'G', null, '6.707', 'Triple mortal atrás agrupado (Magaña)', 'Magaña', 'Tres mortales atrás agrupados seguidos tras soltar en el balanceo largo adelante desde suspensión, hasta caer de pie.', 104, '2026-11-20'::date, 'Claude', '2026-11-20'::date, 5, 'draft', null);

do $element_catalog_seed_reviewed_guard$
declare
  changed_keys text;
begin
  select string_agg(e.element_key, ', ' order by e.element_key)
    into changed_keys
  from zaltyko.catalog_elements e
  join zaltyko.catalog_element_editions ed on ed.id = e.edition_id
  join pg_temp.element_catalog_seed_rows s on s.element_key = e.element_key
  where ed.code = 'fig-wag-2025-2028'
    and e.review_status = 'reviewed'
    and (e.apparatus, e.element_group, e.value_letter, e.value_points, e.fig_reference, e.name, e.short_name, e.description)
        is distinct from (s.apparatus, s.element_group, s.value_letter, s.value_points, s.fig_reference, s.name, s.short_name, s.description)
    and (s.reviewed_on is null or e.reviewed_on is null or s.reviewed_on <= e.reviewed_on);
  if changed_keys is not null then
    raise exception 'Element catalog seed would change reviewed elements without a newer reviewed_on: %', changed_keys;
  end if;
end;
$element_catalog_seed_reviewed_guard$;

insert into zaltyko.catalog_elements
  (edition_id, element_key, discipline, apparatus, element_group, value_letter, value_points, fig_reference, name, short_name, description, source_page, source_checked_on, drafted_by, drafted_on, batch, review_status, reviewed_on)
select ed.id, s.element_key, ed.discipline, s.apparatus, s.element_group, s.value_letter, s.value_points, s.fig_reference, s.name, s.short_name, s.description, s.source_page, s.source_checked_on, s.drafted_by, s.drafted_on, s.batch, s.review_status, s.reviewed_on
from pg_temp.element_catalog_seed_rows s
cross join zaltyko.catalog_element_editions ed
where ed.code = 'fig-wag-2025-2028'
on conflict (edition_id, element_key) do update set
  discipline = excluded.discipline,
  apparatus = excluded.apparatus,
  element_group = excluded.element_group,
  value_letter = excluded.value_letter,
  value_points = excluded.value_points,
  fig_reference = excluded.fig_reference,
  name = excluded.name,
  short_name = excluded.short_name,
  description = excluded.description,
  source_page = excluded.source_page,
  source_checked_on = excluded.source_checked_on,
  drafted_by = excluded.drafted_by,
  drafted_on = excluded.drafted_on,
  batch = excluded.batch,
  review_status = case when catalog_elements.review_status = 'reviewed' then 'reviewed' else excluded.review_status end,
  reviewed_on = case when catalog_elements.review_status = 'reviewed' then greatest(catalog_elements.reviewed_on, excluded.reviewed_on) else excluded.reviewed_on end,
  updated_at = now()
where (catalog_elements.discipline, catalog_elements.apparatus, catalog_elements.element_group, catalog_elements.value_letter, catalog_elements.value_points, catalog_elements.fig_reference, catalog_elements.name, catalog_elements.short_name, catalog_elements.description, catalog_elements.source_page, catalog_elements.source_checked_on, catalog_elements.drafted_by, catalog_elements.drafted_on, catalog_elements.batch, catalog_elements.review_status, catalog_elements.reviewed_on)
  is distinct from (excluded.discipline, excluded.apparatus, excluded.element_group, excluded.value_letter, excluded.value_points, excluded.fig_reference, excluded.name, excluded.short_name, excluded.description, excluded.source_page, excluded.source_checked_on, excluded.drafted_by, excluded.drafted_on, excluded.batch, case when catalog_elements.review_status = 'reviewed' then 'reviewed' else excluded.review_status end, case when catalog_elements.review_status = 'reviewed' then greatest(catalog_elements.reviewed_on, excluded.reviewed_on) else excluded.reviewed_on end);

commit;
